-- Generated by the ingest-origin-claim-fence lane. Reverse of 20261105062010: restores 20261105058010's exact
-- sessions.ingest_lock_fences (every caller takes the user's fence row FOR UPDATE again; owner/ACL unchanged), then
-- drops the three origin-scoped entry points, the two owner-only helpers and the mark table (rows exist only inside
-- an in-flight call). A Worker still running with INGEST_ORIGIN_CLAIM_FENCE=on falls back to the per-user entry
-- points on 42883 (ledger-sql.ts). Code only: running it against a hosted database needs the user's OK.
-- Explicit transaction: guard, restore, drops and ledger removal are atomic; on an error the caller must ROLLBACK
-- (or disconnect); nothing is committed. Refused (55000) unless 062010 is applied with this exact checksum, and
-- while a later upstream migration is applied.
BEGIN;
SELECT pg_advisory_xact_lock(961996,1); -- same namespace as the real migrator
DO $rollback_guard$ DECLARE v_sha text; BEGIN
 IF to_regclass('sessions.__96bulls_migrations')IS NULL
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='origin claim fence: migration ledger required';END IF;
 LOCK TABLE sessions.__96bulls_migrations IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM sessions.__96bulls_migrations WHERE name LIKE 'upstream:%' AND name COLLATE "C">'upstream:20261105062010_ingest_origin_claim_fence.sql')
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='origin claim fence: a later migration is applied; roll it back first';END IF;
 SELECT sha256 INTO v_sha FROM sessions.__96bulls_migrations WHERE name='upstream:20261105062010_ingest_origin_claim_fence.sql' FOR UPDATE;
 IF NOT FOUND OR v_sha IS DISTINCT FROM '154039c59599c4096ba62ff12da8a680d9862264763554273fd4f9a79e990b4c'
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='origin claim fence: own applied checksum required';END IF;
END $rollback_guard$;
SET LOCAL lock_timeout='5s';
-- sessions.ingest_lock_fences(text,text,text): restored from 20261105058010.
CREATE OR REPLACE FUNCTION sessions.ingest_lock_fences(p_org text,p_ws text,p_user text)
RETURNS void LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $lock$
BEGIN
 INSERT INTO sessions.ingest_fence_owners VALUES(p_org,p_ws,p_user) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM sessions.ingest_fence_owners AS f
 WHERE f.org_id=p_org AND f.workspace_id=p_ws AND f.user_id=p_user FOR UPDATE;
 IF EXISTS(SELECT 1 FROM sessions.operator_user_erasures AS e
   WHERE e.org_id=p_org AND e.workspace_id=p_ws AND e.user_id=p_user AND e.state<>'bytes_verified') THEN
  RAISE EXCEPTION USING ERRCODE='RH041',
   MESSAGE='operator user erase: uploads for this user are refused until the erase is verified';
 END IF;
END
$lock$;
